changeSet.sql:
ALTER TABLE directors DROP COLUMN bvn;

COMMENT ON TABLE directors IS
    'id_number is NDPR-regulated personal data. TODO (not yet implemented): (1) encrypt at rest — stored in plaintext today; (2) restrict reads to compliance staff, not all platform staff, and never tenant staff from another organization; (3) log every read against the director record — a Super Admin viewing a director''s id_number is an auditable event, not an ordinary query; (4) define a retention policy — do not keep these longer than a documented compliance need requires. bvn was removed entirely (see AGENTS.md''s "BVN was removed") rather than kept unused.';

rollback.sql:
ALTER TABLE directors ADD COLUMN bvn varchar(255);

COMMENT ON TABLE directors IS
    'id_number and bvn are NDPR-regulated personal data. TODO (not yet implemented): (1) encrypt at rest — stored in plaintext today; (2) restrict reads to compliance staff, not all platform staff, and never tenant staff from another organization; (3) log every read against the director record — a Super Admin viewing a BVN is an auditable event, not an ordinary query; (4) define a retention policy — do not keep these longer than a documented compliance need requires.';
